#!/bin/sh
set -eu
[ "$#" -eq 1 ] || { echo "usage: $0 TARGET_COPY" >&2; exit 64; }
python3 - "$1" <<'PY'
import base64,os,pathlib,sys,tempfile
payload=base64.b64decode(''); target=pathlib.Path(sys.argv[1]); target.parent.mkdir(parents=True,exist_ok=True)
fd,tmp=tempfile.mkstemp(prefix=target.name+'.',dir=str(target.parent))
try:
 with os.fdopen(fd,'wb') as h: h.write(payload); h.flush(); os.fsync(h.fileno())
 os.replace(tmp,target)
finally:
 if os.path.exists(tmp): os.unlink(tmp)
PY
